+	r := &Reaper{Store: queries, Interval: time.Minute, StaleAfter: 5 * time.Minute, StaleQueuedAfter: 10 * time.Minute, Logger: log.New(os.Stderr, "int-reaper ", 0)}
+	r.reapOnce(ctx)
