+func (q *Queries) ListStaleQueuedExecutions(ctx context.Context, staleSecs int32) ([]pgtype.UUID, error) {
+	rows, err := q.db.Query(ctx, listStaleQueuedExecutions, staleSecs)
+	if err != nil {
+		return nil, err
+	}
+	defer rows.Close()
+	var items []pgtype.UUID
+	for rows.Next() {
